export const vocabById = Object.fromEntries(VOCABULARY.map((entry) => [entry.id, entry]));

/** Palavras (sem as microfrases). */
export const VOCAB_WORDS = VOCABULARY.filter((entry) => entry.kind === "word");
/** Microfrases úteis. */
export const VOCAB_PHRASES = VOCABULARY.filter((entry) => entry.kind === "phrase");

export function vocabularyByDomain(domain: VocabEntry["domain"]): VocabEntry[] {
  return VOCABULARY.filter((entry) => entry.domain === domain);
}

export function vocabularyByLevel(level: VocabEntry["level"]): VocabEntry[] {
  return VOCABULARY.filter((entry) => entry.level === level);
}
